122	    /// and prevents transmission of further messages,
123	    /// however the device retrains its state.
124	    ///
125	    /// The instance will continue to consume and discard messages
126	    /// on both ends of the device.
127	    pub fn down(&self) {
128	        // ensure exclusive access (to avoid race with "up" call)
129	        let mut enabled = self.enabled.write();
130	
131	        // check if already down
132	        if !(*enabled) {
133	            return;
134	        }
135	
136	        // set mtu
137	        self.mtu.store(0, Ordering::Relaxed);
138	
139	        // avoid transmission from router
