205	    pub fn add_peer(&self, pk: PublicKey) -> bool {
206	        let mut peers = self.peers.write();
207	        if peers.contains_key(&pk) {
208	            return false;
209	        }
210	
211	        // prevent up/down while inserting
212	        let enabled = self.enabled.read();
213	
214	        // create timers (lookup by public key)
215	        let timers = Timers::new::<T, B>(self.clone(), pk, *enabled);
216	
217	        // create new router peer
218	        let peer: router::PeerHandle<B::Endpoint, PeerInner<T, B>, T::Writer, B::Writer> =
219	            self.router.new_peer(PeerInner {
220	                id: OsRng.gen(),
221	                pk,
222	                wg: self.clone(),
223	                walltime_last_handshake: Mutex::new(None),
224	                last_handshake_sent: Mutex::new(Instant::now() - TIME_HORIZON),
225	                handshake_queued: AtomicBool::new(false),
226	                rx_bytes: AtomicU64::new(0),
227	                tx_bytes: AtomicU64::new(0),
228	                timers: RwLock::new(timers),
229	            });
230	
231	        // finally, add the peer to the handshake device
232	        peers.add(pk, peer).is_ok()
233	    }
