235	    /// Begin consuming messages from the reader.
236	    /// Multiple readers can be added to support multi-queue and individual Ipv6/Ipv4 sockets interfaces
237	    ///
238	    /// Any previous reader thread is stopped by closing the previous reader,
239	    /// which unblocks the thread and causes an error on reader.read
240	    pub fn add_udp_reader(&self, reader: B::Reader) {
241	        let wg = self.clone();
242	        thread::spawn(move || {
243	            udp_worker(&wg, reader);
244	        });
245	    }
246	
247	    pub fn set_writer(&self, writer: B::Writer) {
248	        self.router.set_outbound_writer(writer);
249	    }
